pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 limit, uint256 wrongAmount) internal {
        wrongAmount = bound(wrongAmount, 0, 1000000000000000000000000000000);
        limit = bound(limit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(limit > 0);
        vm.assume(wrongAmount != limit);
        try c.AdjustBetAmounts(limit) {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        bool revertedWrong;
        try c.wager{value: wrongAmount}() { revertedWrong = false; } catch { revertedWrong = true; }
        bool okAfterWrong;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { okAfterWrong = __r; } catch { return; }
        vm.assume(address(this).balance >= limit);
        try c.wager{value: limit}() {} catch { return; }
        bool okAfterRight;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { okAfterRight = __r; } catch { return; }
        assertTrue(revertedWrong && !okAfterWrong && okAfterRight && c.currentBetLimit() == limit);
    }

    function testFuzz_run(uint256 limit, uint256 wrongAmount) public {
        _run(limit, wrongAmount);
    }

    receive() external payable {}
}
